<div class="split"><div class="card"><h2>Selecciona los productos</h2><div class="formgrid"><div class="f"><label>Buscar</label><input id="search" oninput="renderProducts()" placeholder="Nombre del producto"></div><div class="f"><label>Categoría</label><select id="category" onchange="renderProducts()"><option value="">Todas</option>@foreach($categorias as $cat)<option value="{{ $cat->id_categoria }}">{{ $cat->nombre }}</option>@endforeach</select></div></div><div class="product-grid" id="products"></div></div><div class="card"><h2>Carrito</h2><div id="cart"><p class="muted">Agrega productos al carrito.</p></div><div class="tot"><span>Total</span><span>Bs <b id="total">0.00</b></span></div><h2>Pagos</h2><div id="payments"></div><button type="button" class="btn out small" onclick="addPayment()">+ Añadir método</button><p id="error" class="error" style="display:none"></p><button type="button" class="btn" style="width:100%;margin-top:12px" onclick="saveSale()" @disabled(!$cajaAbierta)>✓ Confirmar venta</button></div></div>
<script>
const products=@json($productosData);const methods=@json($metodosData);let cart=[],payments=[{methodId:methods[0]?.id||'',amount:0}];const money=n=>Number(n||0).toFixed(2);
function image(p){if(p.photo)return '/storage/'+p.photo;let n=p.name.toLowerCase();return '/images/productos/'+(n.includes('coca')?'cocacola.jpg.jpeg':n.includes('pollo')?'saltena-pollo.jpeg':n.includes('queso')?'saltena-queso.jpeg':n.includes('mixta')?'saltena-mixta.jpeg':'saltena-carne.jpeg')}
function renderProducts(){let s=document.getElementById('search').value.toLowerCase(),c=document.getElementById('category').value;document.getElementById('products').innerHTML=products.filter(p=>(!s||p.name.toLowerCase().includes(s))&&(!c||p.category==c)).map(p=>`<div class="product-card"><img src="${image(p)}"><button onclick="add(${p.id})">${p.name}<br><span class="muted">Bs ${money(p.price)} · stock ${p.stock}</span></button></div>`).join('')||'<p class="muted">No hay productos disponibles.</p>'}
function add(id){let p=products.find(x=>x.id===id),x=cart.find(x=>x.id===id);if(!p||p.stock<1)return showError('Producto sin stock disponible.');if(x){if(x.qty>=p.stock)return showError('No puedes superar el stock disponible.');x.qty++}else cart.push({id,qty:1});renderCart()}
function renderCart(){document.getElementById('cart').innerHTML=cart.map(x=>{let p=products.find(y=>y.id===x.id);return `<div class="cart-line"><span>${p.name}<br><small>${x.qty} × Bs ${money(p.price)}</small></span><span><button class="btn out small" onclick="change(${x.id},-1)">−</button> ${x.qty} <button class="btn out small" onclick="change(${x.id},1)">+</button> <button class="btn out small" onclick="removeItem(${x.id})">×</button></span></div>`}).join('')||'<p class="muted">Agrega productos al carrito.</p>';document.getElementById('total').textContent=money(total());renderPayments()}
function change(id,n){let x=cart.find(y=>y.id===id),p=products.find(y=>y.id===id);if(!x)return;if(n>0&&x.qty>=p.stock)return showError('Stock insuficiente.');x.qty+=n;if(x.qty<1)removeItem(id);else renderCart()}function removeItem(id){cart=cart.filter(x=>x.id!==id);renderCart()}function total(){return cart.reduce((s,x)=>s+products.find(p=>p.id===x.id).price*x.qty,0)}function addPayment(){payments.push({methodId:methods[0]?.id||'',amount:0});renderPayments()}
function renderPayments(){document.getElementById('payments').innerHTML=payments.map((p,i)=>`<div class="formgrid" style="grid-template-columns:1fr 110px auto"><select onchange="payments[${i}].methodId=Number(this.value)">${methods.map(m=>`<option value="${m.id}" ${p.methodId==m.id?'selected':''}>${m.name}</option>`).join('')}</select><input type="number" min="0.01" step=".01" value="${p.amount||''}" oninput="payments[${i}].amount=Number(this.value)"><button type="button" class="btn out small" onclick="payments.splice(${i},1);renderPayments()">×</button></div>`).join('')}
function showError(msg){let e=document.getElementById('error');e.textContent=msg;e.style.display='block'}async function saveSale(){document.getElementById('error').style.display='none';if(!cart.length)return showError('Agrega al menos un producto.');if(Math.abs(payments.reduce((s,p)=>s+Number(p.amount||0),0)-total())>.005)return showError('La suma de los pagos debe coincidir con el total.');let r=await fetch('{{ route('ventas.store') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({id_sucursal:{{ $branchId }},detalles:cart.map(x=>({id_producto:x.id,cantidad:x.qty})),pagos:payments.map(p=>({id_metodo_pago:Number(p.methodId),importe:p.amount,verificado:false}))})});if(r.ok){let v=await r.json();location.href='{{ url('ventas') }}/'+v.id_venta}else{let d=await r.json();showError(d.message||Object.values(d.errors||{}).flat().join(' ')||'No se pudo registrar la venta.')}}renderProducts();renderCart();
</script>
